"use strict";

const BOC_RATES_URL = "https://www.bankofchina.com/sourcedb/whpj/";
const CACHE_SECONDS = 3 * 60 * 60;
const STALE_SECONDS = 7 * 24 * 60 * 60;
const REQUEST_TIMEOUT_MS = 7000;

let lastSuccessfulQuote = null;

function sendJson(response, statusCode, payload, cacheable = false) {
  response.statusCode = statusCode;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("X-Content-Type-Options", "nosniff");

  if (cacheable) {
    response.setHeader("Cache-Control", "public, max-age=0, must-revalidate");
    response.setHeader(
      "CDN-Cache-Control",
      `public, s-maxage=${CACHE_SECONDS}, stale-while-revalidate=${STALE_SECONDS}, stale-if-error=${STALE_SECONDS}`
    );
    response.setHeader(
      "Vercel-CDN-Cache-Control",
      `public, s-maxage=${CACHE_SECONDS}, stale-while-revalidate=${STALE_SECONDS}, stale-if-error=${STALE_SECONDS}`
    );
  } else {
    response.setHeader("Cache-Control", "private, no-store, max-age=0");
  }

  response.end(JSON.stringify(payload));
}

function cleanCell(value) {
  return String(value || "")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/\s+/g, " ")
    .trim();
}

function parseRate(value, label) {
  const parsed = Number.parseFloat(String(value).replace(/,/g, ""));
  if (!Number.isFinite(parsed) || parsed <= 0 || parsed >= 10000) {
    throw new Error(`Invalid ${label}`);
  }
  return parsed;
}

function parseAustralianDollarQuote(html) {
  const row = html.match(
    /<tr[^>]*data-currency=["']澳大利亚元["'][^>]*>([\s\S]*?)<\/tr>/i
  );
  if (!row) throw new Error("AUD row was not found");

  const cells = Array.from(row[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi), (match) =>
    cleanCell(match[1])
  );
  if (cells.length < 7 || cells[0] !== "澳大利亚元") {
    throw new Error("AUD row structure changed");
  }

  const spotBuyPer100 = parseRate(cells[1], "spot buy rate");
  const spotSellPer100 = parseRate(cells[3], "spot sell rate");
  const publishedAt = cells[6];

  if (!/^\d{4}\/\d{2}\/\d{2} \d{2}:\d{2}:\d{2}$/.test(publishedAt)) {
    throw new Error("Invalid publication time");
  }
  if (spotSellPer100 < spotBuyPer100) {
    throw new Error("Unexpected buy/sell relationship");
  }

  return {
    currency: "AUD",
    quoteCurrency: "CNY",
    spotBuy: spotBuyPer100,
    spotSell: spotSellPer100,
    officialUnit: "CNY per 100 AUD",
    officialSpotBuy: spotBuyPer100,
    officialSpotSell: spotSellPer100,
    publishedAt: publishedAt.replaceAll("/", "-"),
    source: {
      name: "中国银行",
      url: BOC_RATES_URL
    },
    fetchedAt: new Date().toISOString(),
    stale: false
  };
}

async function fetchOfficialRatesPage(url) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(url, {
      signal: controller.signal,
      headers: {
        Accept: "text/html,application/xhtml+xml",
        "User-Agent": "Aden-Space-Exchange-Card/1.0 (+https://blog.adenxie.com.cn/)"
      }
    });
    if (!response.ok) throw new Error(`Bank of China returned ${response.status}`);
    return await response.text();
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchOfficialRates() {
  return fetchOfficialRatesPage(BOC_RATES_URL);
}

module.exports = async function audCnyQuote(request, response) {
  if (request.method && request.method !== "GET") {
    response.setHeader("Allow", "GET");
    sendJson(response, 405, { error: "method_not_allowed" });
    return;
  }

  try {
    const quote = parseAustralianDollarQuote(await fetchOfficialRates());
    lastSuccessfulQuote = quote;
    sendJson(response, 200, quote, true);
  } catch (error) {
    if (lastSuccessfulQuote) {
      sendJson(
        response,
        200,
        {
          ...lastSuccessfulQuote,
          stale: true,
          fetchError: error?.name === "AbortError" ? "source_timeout" : "source_unavailable"
        },
        true
      );
      return;
    }

    sendJson(response, 502, {
      error: error?.name === "AbortError" ? "source_timeout" : "source_unavailable"
    });
  }
};

module.exports.parseAustralianDollarQuote = parseAustralianDollarQuote;

"use strict";

const FORECAST_ENDPOINT = "https://api.open-meteo.com/v1/forecast";
const CURRENT_FIELDS = [
  "temperature_2m",
  "apparent_temperature",
  "relative_humidity_2m",
  "weather_code",
  "wind_speed_10m",
  "is_day"
].join(",");

function readHeader(request, name) {
  const headers = request?.headers;
  if (!headers) return null;
  if (typeof headers.get === "function") return headers.get(name);
  const value = headers[name] ?? headers[name.toLowerCase()];
  return Array.isArray(value) ? value[0] : value ?? null;
}

function decodeHeader(value) {
  if (!value) return "";
  try {
    return decodeURIComponent(String(value).replace(/\+/g, "%20"));
  } catch (_) {
    return String(value);
  }
}

function sendJson(response, statusCode, payload) {
  response.statusCode = statusCode;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("Cache-Control", "private, no-store, max-age=0");
  response.setHeader("X-Content-Type-Options", "nosniff");
  response.end(JSON.stringify(payload));
}

function isValidCoordinate(latitude, longitude) {
  return (
    Number.isFinite(latitude) &&
    Number.isFinite(longitude) &&
    latitude >= -90 &&
    latitude <= 90 &&
    longitude >= -180 &&
    longitude <= 180
  );
}

function parseCoordinate(value) {
  if (value === null || value === undefined || String(value).trim() === "") return Number.NaN;
  return Number(value);
}

module.exports = async function visitorWeather(request, response) {
  if (request.method && request.method !== "GET") {
    response.setHeader("Allow", "GET");
    sendJson(response, 405, { error: "method_not_allowed" });
    return;
  }

  const latitude = parseCoordinate(readHeader(request, "x-vercel-ip-latitude"));
  const longitude = parseCoordinate(readHeader(request, "x-vercel-ip-longitude"));

  if (!isValidCoordinate(latitude, longitude)) {
    sendJson(response, 503, { error: "location_unavailable" });
    return;
  }

  const city = decodeHeader(readHeader(request, "x-vercel-ip-city"));
  const region = decodeHeader(readHeader(request, "x-vercel-ip-country-region"));
  const country = decodeHeader(readHeader(request, "x-vercel-ip-country"));
  const label = city || region || country || "当前位置";

  const query = new URLSearchParams({
    latitude: latitude.toFixed(4),
    longitude: longitude.toFixed(4),
    current: CURRENT_FIELDS,
    daily: "sunrise,sunset",
    timezone: "auto",
    forecast_days: "1"
  });
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 7000);

  try {
    const weatherResponse = await fetch(`${FORECAST_ENDPOINT}?${query}`, {
      signal: controller.signal,
      headers: { Accept: "application/json" }
    });
    if (!weatherResponse.ok) throw new Error(`Open-Meteo returned ${weatherResponse.status}`);

    const forecast = await weatherResponse.json();
    if (!forecast?.current || !forecast?.timezone) throw new Error("Incomplete weather response");

    sendJson(response, 200, {
      location: {
        label,
        city,
        region,
        country,
        timezone: forecast.timezone,
        source: "vercel-ip",
        approximate: true
      },
      current: forecast.current,
      daily: forecast.daily
    });
  } catch (error) {
    sendJson(response, 502, {
      error: error?.name === "AbortError" ? "weather_timeout" : "weather_unavailable"
    });
  } finally {
    clearTimeout(timeout);
  }
};

:root {
  --aden-void: #070a0f;
  --aden-panel: #101821;
  --aden-panel-raised: #151f2b;
  --aden-signal: #f2e94e;
  --aden-amber: #ffb800;
  --aden-cyan: #18d5e8;
  --aden-ink: #e8edf2;
  --aden-muted: #8e99a8;
  --aden-interface-font: "Segoe UI Variable", "MiSans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --aden-display-font: "Chillax-Variable", var(--aden-interface-font);
  --aden-body-font: var(--aden-interface-font);
  --aden-mono-font: "Geist Mono", "Cascadia Code", "SFMono-Regular", "Microsoft YaHei", monospace;
}

html.light {
  --aden-signal: #756800;
  --aden-amber: #8a6200;
  --aden-cyan: #0c6672;
  --background-color: #f3f2e8;
  --background-color-transparent: rgb(243 242 232 / 72%);
  --background-color-transparent-80: rgb(243 242 232 / 88%);
  --second-background-color: #e9eadf;
  --third-background-color: #dfe3da;
  --third-background-color-transparent: rgb(223 227 218 / 72%);
  --primary-color: #786500;
  --first-text-color: #111821;
  --second-text-color: #26313b;
  --third-text-color: #5f6972;
  --default-text-color: #18212b;
  --border-color: rgb(7 10 15 / 15%);
  --selection-color: #d7cb22;
  --link-color: #0c6672;
  --scrollbar-color: #a79f31;
  --scrollbar-color-hover: #756f18;
  --scroll-bar-bg-color: #dedfd5;
  color-scheme: light;
}

html.dark {
  --background-color: var(--aden-void);
  --background-color-transparent: rgb(7 10 15 / 72%);
  --background-color-transparent-80: rgb(7 10 15 / 88%);
  --second-background-color: var(--aden-panel);
  --third-background-color: var(--aden-panel-raised);
  --third-background-color-transparent: rgb(21 31 43 / 74%);
  --primary-color: var(--aden-signal);
  --first-text-color: var(--aden-ink);
  --second-text-color: #c7d0da;
  --third-text-color: var(--aden-muted);
  --default-text-color: #d5dce3;
  --border-color: rgb(242 233 78 / 15%);
  --selection-color: var(--aden-signal);
  --link-color: var(--aden-cyan);
  --shadow-color-1: rgb(242 233 78 / 9%);
  --shadow-color-2: rgb(0 0 0 / 34%);
  --shadow-hover-color: rgb(24 213 232 / 14%);
  --scrollbar-color: #746f2b;
  --scrollbar-color-hover: var(--aden-signal);
  --scroll-bar-bg-color: #0b1017;
  color-scheme: dark;
}

body {
  font-family: var(--aden-body-font);
  text-rendering: optimizeLegibility;
}

::selection {
  color: var(--aden-void);
  background: var(--aden-signal);
}

.navbar-container {
  border-bottom: 1px solid rgb(242 233 78 / 28%);
  box-shadow: 0 10px 32px rgb(0 0 0 / 18%);
}

.navbar-container .navbar-list,
.home-article-meta-info-container,
.article-meta-info {
  font-family: var(--aden-mono-font);
}

.navbar-container .logo-title {
  font-family: var(--aden-display-font);
  font-weight: 500;
  letter-spacing: -0.025em;
}

.navbar-container .navbar-item a.active,
.navbar-container .navbar-item a:hover {
  color: var(--aden-signal) !important;
}

.home-banner-background::after {
  position: absolute;
  inset: 0;
  z-index: 1;
  content: "";
  pointer-events: none;
  background:
    repeating-linear-gradient(0deg, transparent 0 3px, rgb(7 10 15 / 8%) 3px 4px),
    linear-gradient(100deg, rgb(7 10 15 / 90%) 0%, rgb(7 10 15 / 58%) 43%, rgb(7 10 15 / 14%) 78%),
    linear-gradient(0deg, rgb(7 10 15 / 76%) 0%, transparent 48%);
}

.home-banner-background img {
  object-position: center 48%;
}

.home-banner-container > .content {
  z-index: 2;
}

.home-banner-container .description {
  max-width: min(88vw, 920px);
  align-items: flex-start;
  padding: 0 5vw;
  color: #fff;
  font-family: var(--aden-display-font);
  font-weight: 500;
  text-align: left;
  letter-spacing: -0.035em;
  text-shadow: 0 2px 26px rgb(0 0 0 / 58%);
}

.home-banner-container .description::before {
  display: block;
  margin-bottom: 1rem;
  color: var(--aden-signal);
  font-family: var(--aden-mono-font);
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.24em;
  content: "ADEN // FIELD NOTES";
}

.home-banner-container .description::after {
  width: min(15rem, 48vw);
  height: 3px;
  margin-top: 1.15rem;
  content: "";
  background: linear-gradient(90deg, var(--aden-signal) 0 72%, var(--aden-cyan) 72% 82%, transparent 82%);
}

.home-banner-container .description p {
  margin-top: 0.9rem;
  color: #f5f5ee;
  font-family: var(--aden-body-font) !important;
  font-weight: 500;
  letter-spacing: 0.1em;
}

.home-banner-container .social-contacts,
.home-banner-container [onclick="scrollToMain()"] {
  border-color: color-mix(in srgb, var(--aden-signal) 42%, transparent) !important;
  border-radius: 8px !important;
  background: rgb(7 10 15 / 68%) !important;
  box-shadow: 0 0 24px rgb(24 213 232 / 8%);
}

.home-banner-container .social-contact-item a,
.home-banner-container .social-contact-item a i,
.home-banner-container [onclick="scrollToMain()"],
.home-banner-container [onclick="scrollToMain()"] i {
  color: #d5dce3 !important;
}

.home-banner-container .social-contact-item a:hover,
.home-banner-container .social-contact-item a:hover i,
.home-banner-container [onclick="scrollToMain()"]:hover,
.home-banner-container [onclick="scrollToMain()"]:hover i {
  color: var(--aden-signal) !important;
}

.home-content-container .home-article-list .home-article-item {
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--aden-signal) 25%, var(--border-color));
  background: linear-gradient(145deg, color-mix(in srgb, var(--second-background-color) 94%, var(--aden-cyan)), var(--second-background-color) 36%);
}

html.dark .home-content-container .home-article-list .home-article-item {
  background: linear-gradient(145deg, rgb(16 24 33 / 98%), rgb(7 10 15 / 98%));
}

html.light .home-content-container .home-article-list .home-article-item {
  background: linear-gradient(145deg, #f8f7ed, #e9eadf);
}

.home-content-container .home-article-list .home-article-item::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  z-index: 3;
  height: 3px;
  content: "";
  background: linear-gradient(90deg, var(--aden-signal) 0 24%, transparent 24% 27%, var(--aden-cyan) 27% 34%, transparent 34%);
}

.home-article-thumbnail {
  height: 190px !important;
}

html .home-content-container .home-article-list .home-article-item .home-article-title {
  font-family: "Geist Mono", "Cascadia Code", "Microsoft YaHei", monospace;
  letter-spacing: -0.025em;
}

.home-content-container .home-article-list .home-article-item .home-article-title a:hover,
.home-content-container .home-article-list .home-article-item .home-article-meta-info-container > a:hover {
  color: var(--aden-signal);
}

.home-sidebar-container .sidebar-content,
.home-sidebar-container .sidebar-links {
  border-left: 3px solid var(--aden-signal);
}

.cyber-weather-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  margin-bottom: 1.15rem;
  border: 1px solid color-mix(in srgb, var(--aden-signal) 38%, var(--border-color));
  border-radius: 12px;
  color: var(--second-text-color);
  background:
    linear-gradient(112deg, color-mix(in srgb, var(--aden-signal) 5%, transparent), transparent 42%),
    var(--second-background-color);
  box-shadow: 0 16px 42px rgb(0 0 0 / 14%);
  font-family: var(--aden-mono-font);
}

html.dark .cyber-weather-card {
  background:
    linear-gradient(112deg, rgb(242 233 78 / 7%), transparent 42%),
    linear-gradient(145deg, rgb(16 24 33 / 98%), rgb(7 10 15 / 98%));
  box-shadow: 0 18px 50px rgb(0 0 0 / 28%);
}

html.light .cyber-weather-card {
  border-color: rgb(117 104 0 / 34%);
  background:
    linear-gradient(112deg, rgb(117 104 0 / 5%), transparent 42%),
    linear-gradient(145deg, #f8f7ed, #e9eadf);
  box-shadow: 0 14px 34px rgb(17 24 33 / 10%);
}

html.light .cyber-weather-icon {
  text-shadow: none;
}

.cyber-weather-card::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  z-index: 2;
  height: 3px;
  content: "";
  background: linear-gradient(90deg, var(--aden-signal) 0 62%, var(--aden-cyan) 62% 72%, transparent 72%);
}

.cyber-weather-card::after {
  position: absolute;
  top: 3px;
  bottom: 0;
  left: -35%;
  z-index: -1;
  width: 32%;
  content: "";
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgb(24 213 232 / 7%), transparent);
  transform: skewX(-18deg);
  animation: aden-weather-scan 9s ease-in-out infinite;
}

.cyber-weather-header,
.cyber-weather-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.7rem 1rem;
  color: var(--third-text-color);
  font-size: 0.65rem;
  font-weight: 650;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.cyber-weather-header {
  gap: 0.75rem;
  border-bottom: 1px solid var(--border-color);
}

.cyber-weather-footer {
  border-top: 1px solid var(--border-color);
}

.cyber-weather-footer a {
  color: var(--link-color);
  text-decoration: none;
}

.cyber-weather-live {
  display: inline-flex;
  min-width: 0;
  gap: 0.5rem;
  align-items: center;
  white-space: nowrap;
  color: var(--aden-signal);
}

.cyber-weather-live [data-location="name"],
.cyber-weather-coords {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cyber-weather-live [data-location="name"] {
  max-width: 18rem;
}

.cyber-weather-coords {
  max-width: 45%;
  flex: 0 0 auto;
  text-align: right;
}

.cyber-weather-live i {
  width: 0.46rem;
  height: 0.46rem;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--aden-amber);
  box-shadow: 0 0 0 4px rgb(255 184 0 / 10%), 0 0 13px rgb(255 184 0 / 46%);
}

.cyber-weather-card.is-online .cyber-weather-live i {
  background: var(--aden-cyan);
  box-shadow: 0 0 0 4px rgb(24 213 232 / 10%), 0 0 13px rgb(24 213 232 / 52%);
}

.cyber-weather-card.is-offline .cyber-weather-live i {
  background: #ff5b5b;
  box-shadow: 0 0 0 4px rgb(255 91 91 / 10%), 0 0 13px rgb(255 91 91 / 48%);
}

.cyber-weather-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(190px, 0.85fr) minmax(210px, 0.8fr);
  min-height: 138px;
}

.cyber-clock-block,
.cyber-current-weather,
.cyber-weather-metrics {
  min-width: 0;
  padding: 1.05rem 1.2rem;
}

.cyber-clock-block,
.cyber-current-weather {
  border-right: 1px solid var(--border-color);
}

.cyber-clock-block {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.cyber-data-label {
  margin-bottom: 0.34rem;
  color: var(--third-text-color);
  font-size: 0.64rem;
  font-weight: 650;
  letter-spacing: 0.13em;
}

.cyber-clock {
  color: var(--first-text-color);
  font-size: clamp(2.25rem, 5vw, 4.45rem);
  font-variant-numeric: tabular-nums;
  font-weight: 520;
  line-height: 0.96;
  letter-spacing: -0.075em;
  text-shadow: 0 0 26px rgb(24 213 232 / 10%);
}

.cyber-clock::first-letter {
  color: var(--aden-signal);
}

.cyber-date {
  margin-top: 0.55rem;
  color: var(--third-text-color);
  font-family: var(--aden-body-font);
  font-size: 0.8rem;
  letter-spacing: 0.05em;
}

.cyber-current-weather {
  display: flex;
  gap: 0.85rem;
  align-items: center;
}

.cyber-weather-icon {
  width: 2.75rem;
  flex: 0 0 auto;
  color: var(--aden-signal);
  font-size: 2.4rem;
  line-height: 1;
  text-align: center;
  text-shadow: 0 0 22px rgb(242 233 78 / 22%);
}

.cyber-current-weather > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.cyber-temperature {
  color: var(--first-text-color);
  font-size: 2rem;
  font-variant-numeric: tabular-nums;
  font-weight: 650;
  line-height: 1;
}

.cyber-condition {
  margin-top: 0.36rem;
  overflow-wrap: anywhere;
  color: var(--second-text-color);
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  line-height: 1.5;
  white-space: normal;
}

.cyber-feels-like {
  margin-top: 0.25rem;
  color: var(--third-text-color);
  font-family: var(--aden-body-font);
  font-size: 0.72rem;
}

.cyber-weather-metrics {
  display: grid;
  grid-template-rows: repeat(3, 1fr);
  margin: 0;
}

.cyber-weather-metrics > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px dashed color-mix(in srgb, var(--border-color) 72%, transparent);
}

.cyber-weather-metrics > div:last-child {
  border-bottom: 0;
}

.cyber-weather-metrics dt {
  color: var(--third-text-color);
  font-size: 0.61rem;
  font-weight: 650;
  letter-spacing: 0.1em;
}

.cyber-weather-metrics dd {
  margin: 0;
  color: var(--first-text-color);
  font-size: 0.78rem;
  font-variant-numeric: tabular-nums;
  font-weight: 650;
}

@keyframes aden-weather-scan {
  0%,
  58% {
    left: -35%;
    opacity: 0;
  }

  65% {
    opacity: 1;
  }

  88%,
  100% {
    left: 115%;
    opacity: 0;
  }
}

.cyber-exchange-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  margin-bottom: 1.15rem;
  border: 1px solid color-mix(in srgb, var(--aden-cyan) 30%, var(--border-color));
  border-radius: 12px;
  color: var(--second-text-color);
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--aden-cyan) 5%, transparent), transparent 45%),
    var(--second-background-color);
  box-shadow: 0 16px 42px rgb(0 0 0 / 14%);
  font-family: var(--aden-mono-font);
}

html.dark .cyber-exchange-card {
  background:
    linear-gradient(100deg, rgb(24 213 232 / 6%), transparent 45%),
    linear-gradient(145deg, rgb(16 24 33 / 98%), rgb(7 10 15 / 98%));
  box-shadow: 0 18px 50px rgb(0 0 0 / 28%);
}

html.light .cyber-exchange-card {
  border-color: rgb(12 102 114 / 28%);
  background:
    linear-gradient(100deg, rgb(12 102 114 / 5%), transparent 45%),
    linear-gradient(145deg, #f8f7ed, #e9eadf);
  box-shadow: 0 14px 34px rgb(17 24 33 / 10%);
}

.cyber-exchange-card::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  z-index: 2;
  height: 3px;
  content: "";
  background: linear-gradient(90deg, var(--aden-cyan) 0 34%, transparent 34% 38%, var(--aden-signal) 38% 72%, transparent 72%);
}

.cyber-exchange-header,
.cyber-exchange-footer {
  display: flex;
  gap: 1rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.7rem 1rem;
  color: var(--third-text-color);
  font-size: 0.65rem;
  font-weight: 650;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.cyber-exchange-header {
  border-bottom: 1px solid var(--border-color);
}

.cyber-exchange-footer {
  border-top: 1px solid var(--border-color);
}

.cyber-exchange-footer a {
  color: var(--link-color);
  text-decoration: none;
  white-space: nowrap;
}

.cyber-exchange-pair {
  display: inline-flex;
  gap: 0.5rem;
  align-items: center;
  color: var(--aden-cyan);
}

.cyber-exchange-pair i {
  width: 0.46rem;
  height: 0.46rem;
  border-radius: 50%;
  background: var(--aden-amber);
  box-shadow: 0 0 0 4px rgb(255 184 0 / 10%), 0 0 13px rgb(255 184 0 / 46%);
}

.cyber-exchange-card.is-online .cyber-exchange-pair i {
  background: var(--aden-cyan);
  box-shadow: 0 0 0 4px rgb(24 213 232 / 10%), 0 0 13px rgb(24 213 232 / 52%);
}

.cyber-exchange-card.is-stale .cyber-exchange-pair i {
  background: var(--aden-signal);
  box-shadow: 0 0 0 4px rgb(242 233 78 / 10%), 0 0 13px rgb(242 233 78 / 36%);
}

.cyber-exchange-card.is-offline .cyber-exchange-pair i {
  background: #ff5b5b;
  box-shadow: 0 0 0 4px rgb(255 91 91 / 10%), 0 0 13px rgb(255 91 91 / 48%);
}

.cyber-exchange-body {
  display: grid;
  grid-template-columns: minmax(210px, 0.72fr) minmax(0, 1.5fr);
  min-height: 128px;
}

.cyber-exchange-intro {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1.05rem 1.2rem;
  border-right: 1px solid var(--border-color);
}

.cyber-exchange-intro strong {
  color: var(--first-text-color);
  font-family: var(--aden-display-font);
  font-size: clamp(1.25rem, 2.7vw, 2rem);
  font-weight: 560;
  letter-spacing: -0.035em;
}

.cyber-exchange-intro > span:last-child {
  margin-top: 0.35rem;
  color: var(--third-text-color);
  font-family: var(--aden-body-font);
  font-size: 0.72rem;
}

.cyber-exchange-quotes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0;
}

.cyber-exchange-quotes > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  padding: 1rem 1.35rem;
}

.cyber-exchange-quotes > div + div {
  border-left: 1px dashed color-mix(in srgb, var(--border-color) 78%, transparent);
}

.cyber-exchange-quotes dt {
  color: var(--third-text-color);
  font-family: var(--aden-body-font);
  font-size: 0.72rem;
}

.cyber-exchange-quotes dt span {
  margin-left: 0.35rem;
  font-family: var(--aden-mono-font);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
}

.cyber-exchange-quotes dd {
  margin: 0.35rem 0 0;
  font-size: clamp(1.75rem, 4.6vw, 3.35rem);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.065em;
}

.cyber-exchange-quotes .is-buy dd {
  color: var(--aden-cyan);
}

.cyber-exchange-quotes .is-sell dd {
  color: var(--aden-signal);
}

.cyber-exchange-notice {
  margin: 0;
  padding: 0.7rem 1rem 0.8rem;
  border-top: 1px dashed color-mix(in srgb, var(--border-color) 70%, transparent);
  color: var(--third-text-color);
  font-family: var(--aden-body-font);
  font-size: 0.67rem;
  line-height: 1.55;
}

.markdown-body {
  color: var(--default-text-color);
  letter-spacing: 0.012em;
}

.markdown-body a {
  color: var(--link-color);
  text-decoration-color: color-mix(in srgb, var(--aden-cyan) 55%, transparent);
  text-underline-offset: 0.18em;
}

.markdown-body h2 {
  padding-left: 0.72rem;
  border-left: 3px solid var(--aden-signal);
  font-family: "Geist Mono", "Cascadia Code", "Microsoft YaHei", monospace;
}

.markdown-body blockquote {
  border-left-color: var(--aden-signal);
  background: color-mix(in srgb, var(--aden-signal) 8%, var(--second-background-color));
}

.dark .markdown-body blockquote {
  background: rgb(242 233 78 / 6%);
}

.article-content img {
  border: 1px solid rgb(242 233 78 / 16%);
  box-shadow: 0 18px 52px rgb(0 0 0 / 24%);
}

.article-content-container .article-title,
.page-template-container .page-template-title {
  font-family: "Geist Mono", "Cascadia Code", "Microsoft YaHei", monospace;
}

.pagination-container .pagination-item.active,
.pagination-container .pagination-item:hover {
  color: var(--aden-void) !important;
  background: var(--aden-signal) !important;
}

footer.footer-container {
  border-top: 1px solid rgb(242 233 78 / 18%);
}

a:focus-visible,
button:focus-visible {
  outline: 3px solid var(--aden-signal);
  outline-offset: 3px;
}

@media (max-width: 960px) {
  .cyber-weather-grid {
    grid-template-columns: minmax(0, 1fr) minmax(190px, 0.85fr);
  }

  .cyber-clock-block {
    grid-column: 1 / -1;
    border-right: 0;
    border-bottom: 1px solid var(--border-color);
  }
}

@media (max-width: 640px) {
  .home-banner-container .description {
    align-items: center;
    padding: 0 1.25rem;
    text-align: center;
  }

  .home-banner-container .description::before {
    margin-bottom: 0.75rem;
    font-size: 0.64rem;
    letter-spacing: 0.18em;
  }

  .home-banner-background img {
    object-position: 57% center;
  }

  .home-article-thumbnail {
    height: 160px !important;
  }

  .cyber-weather-header,
  .cyber-weather-footer {
    padding-right: 0.8rem;
    padding-left: 0.8rem;
    font-size: 0.56rem;
    letter-spacing: 0.08em;
  }

  .cyber-weather-live [data-location="name"] {
    max-width: 10rem;
  }

  .cyber-weather-coords {
    max-width: 55%;
  }

  .cyber-weather-grid {
    grid-template-columns: 1fr 1fr;
  }

  .cyber-clock-block {
    grid-column: 1 / -1;
    border-right: 0;
    border-bottom: 1px solid var(--border-color);
  }

  .cyber-current-weather,
  .cyber-weather-metrics {
    padding: 0.9rem;
  }

  .cyber-clock {
    font-size: clamp(2.65rem, 15vw, 4rem);
  }

  .cyber-condition {
    max-width: 9rem;
  }

  .cyber-exchange-header,
  .cyber-exchange-footer {
    align-items: flex-start;
    padding-right: 0.8rem;
    padding-left: 0.8rem;
    font-size: 0.56rem;
    letter-spacing: 0.08em;
  }

  .cyber-exchange-header {
    align-items: center;
    white-space: nowrap;
  }

  .cyber-exchange-body {
    grid-template-columns: 1fr;
  }

  .cyber-exchange-intro {
    padding: 0.9rem;
    border-right: 0;
    border-bottom: 1px solid var(--border-color);
  }

  .cyber-exchange-quotes > div {
    padding: 0.95rem 0.85rem;
  }

  .cyber-exchange-quotes dd {
    font-size: clamp(1.65rem, 9vw, 2.5rem);
  }

  .cyber-exchange-footer {
    flex-direction: column;
    gap: 0.35rem;
  }

  .cyber-exchange-notice {
    padding-right: 0.8rem;
    padding-left: 0.8rem;
    font-size: 0.62rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

(() => {
  "use strict";

  const QUOTE_URL = "/api/aud-cny?v=2";
  const CACHE_KEY = "aden-aud-cny-v2";
  const CACHE_TTL = 3 * 60 * 60 * 1000;
  const FALLBACK_TTL = 30 * 24 * 60 * 60 * 1000;
  const REQUEST_TIMEOUT_MS = 15000;
  const RETRY_DELAY_MS = 1500;
  const ERROR_MESSAGES = {
    connection_timeout: "连接汇率服务超时",
    connection_failed: "无法连接汇率服务，请检查网络",
    source_timeout: "中行牌价源响应超时",
    source_unavailable: "中行牌价源读取失败",
    invalid_response: "汇率服务返回的数据异常",
    not_found: "汇率接口不存在（404）",
    access_denied: "汇率请求被拒绝",
    rate_limited: "汇率请求过于频繁，请稍后再试",
    service_unavailable: "汇率接口暂不可用"
  };
  let swupBound = false;

  function createCard() {
    const card = document.createElement("section");
    card.className = "cyber-exchange-card is-loading";
    card.id = "aud-cny-exchange-card";
    card.setAttribute("aria-label", "中国银行澳大利亚元兑人民币现汇牌价");
    card.innerHTML = `
      <div class="cyber-exchange-header">
        <span class="cyber-exchange-pair"><i aria-hidden="true"></i> AUD / CNY</span>
        <span>BANK OF CHINA // SPOT FX</span>
      </div>
      <div class="cyber-exchange-body" aria-live="polite">
        <div class="cyber-exchange-intro">
          <span class="cyber-data-label">FOREIGN EXCHANGE TAPE</span>
          <strong>澳元现汇牌价</strong>
          <span>人民币 / 100澳元</span>
        </div>
        <dl class="cyber-exchange-quotes">
          <div class="is-buy">
            <dt>现汇买入价 <span>BUY</span></dt>
            <dd data-exchange="buy">---.--</dd>
          </div>
          <div class="is-sell">
            <dt>现汇卖出价 <span>SELL</span></dt>
            <dd data-exchange="sell">---.--</dd>
          </div>
        </dl>
      </div>
      <div class="cyber-exchange-footer">
        <span data-exchange="status">正在连接中国银行牌价…</span>
        <a href="https://www.bankofchina.com/sourcedb/whpj/" target="_blank" rel="noopener noreferrer">数据来源于中国银行 ↗</a>
      </div>
      <p class="cyber-exchange-notice">现汇买入价与现汇卖出价均为中国银行每100澳元折合人民币的官方牌价。仅供个人非商业展示；实际交易以中国银行网上银行、手机银行、智能柜台或网点柜台价格为准。未经中国银行许可，不得用于商业转载。</p>`;
    return card;
  }

  function formatRate(value) {
    const number = Number(value);
    return Number.isFinite(number) ? `¥${number.toFixed(2)}` : "---.--";
  }

  function formatPublishedAt(value) {
    const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}:\d{2}):\d{2}$/);
    if (!match) return String(value || "时间未知");
    return `${match[1]}-${match[2]}-${match[3]} ${match[4]}`;
  }

  function isValidQuote(payload) {
    return (
      payload?.currency === "AUD" &&
      payload?.officialUnit === "CNY per 100 AUD" &&
      Number.isFinite(Number(payload.spotBuy)) &&
      Number.isFinite(Number(payload.spotSell)) &&
      Number(payload.spotBuy) >= 100 &&
      Number(payload.spotSell) >= 100 &&
      Boolean(payload.publishedAt)
    );
  }

  function renderQuote(card, payload, state = "live", error = null) {
    if (!card?.isConnected || !isValidQuote(payload)) return;
    card.querySelector('[data-exchange="buy"]').textContent = formatRate(payload.spotBuy);
    card.querySelector('[data-exchange="sell"]').textContent = formatRate(payload.spotSell);

    const updated = formatPublishedAt(payload.publishedAt);
    const status = card.querySelector('[data-exchange="status"]');
    if (state === "stale" || payload.stale) status.textContent = `${errorMessage(error || { code: payload.fetchError || "source_unavailable" })} · 显示缓存牌价 · 中行更新 ${updated}`;
    else if (state === "cache") status.textContent = `缓存牌价 · 中行更新 ${updated}`;
    else status.textContent = `中行更新 ${updated} · 三小时缓存`;

    card.classList.remove("is-loading", "is-offline", "is-stale", "is-online");
    card.classList.add(state === "stale" || payload.stale ? "is-stale" : "is-online");
  }

  function readCachedQuote(allowExpired = false) {
    try {
      const cached = JSON.parse(localStorage.getItem(CACHE_KEY));
      if (!cached || !isValidQuote(cached.payload)) return null;
      const age = Date.now() - Number(cached.savedAt || 0);
      const limit = allowExpired ? FALLBACK_TTL : CACHE_TTL;
      return age >= 0 && age < limit ? cached.payload : null;
    } catch (_) {
      try { localStorage.removeItem(CACHE_KEY); } catch (_) { /* Storage is optional. */ }
      return null;
    }
  }

  function cacheQuote(payload) {
    try {
      localStorage.setItem(CACHE_KEY, JSON.stringify({ savedAt: Date.now(), payload }));
    } catch (_) {
      // The live card still works when local storage is unavailable.
    }
  }

  function quoteError(code) {
    return Object.assign(new Error(code), { code });
  }

  function errorMessage(error) {
    return ERROR_MESSAGES[error?.code] || ERROR_MESSAGES.service_unavailable;
  }

  function canRetry(error) {
    return ["connection_timeout", "connection_failed", "source_timeout", "source_unavailable", "service_unavailable"].includes(error?.code);
  }

  async function fetchQuote() {
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    try {
      const response = await fetch(QUOTE_URL, {
        signal: controller.signal,
        headers: { Accept: "application/json" }
      });
      let payload;
      try {
        payload = await response.json();
      } catch (error) {
        if (error?.name === "AbortError") throw error;
        if (response.ok) throw quoteError("invalid_response");
      }
      if (!response.ok) {
        const statusCode = { 404: "not_found", 401: "access_denied", 403: "access_denied", 429: "rate_limited" }[response.status];
        const sourceCode = ["source_timeout", "source_unavailable"].includes(payload?.error) ? payload.error : null;
        throw quoteError(statusCode || sourceCode || "service_unavailable");
      }
      if (!isValidQuote(payload)) throw quoteError("invalid_response");
      return payload;
    } catch (error) {
      if (controller.signal.aborted || error?.name === "AbortError") throw quoteError("connection_timeout");
      throw error?.code ? error : quoteError("connection_failed");
    } finally {
      window.clearTimeout(timeout);
    }
  }

  async function loadQuote(card) {
    const fresh = readCachedQuote(false);
    if (fresh) {
      renderQuote(card, fresh, "cache");
      return;
    }

    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        const payload = await fetchQuote();
        cacheQuote(payload);
        renderQuote(card, payload, payload.stale ? "stale" : "live");
        return;
      } catch (error) {
        if (!card?.isConnected) return;
        if (attempt === 0 && canRetry(error)) {
          card.querySelector('[data-exchange="status"]').textContent = `${errorMessage(error)} · 正在重试（1/1）…`;
          await new Promise(resolve => window.setTimeout(resolve, RETRY_DELAY_MS));
          if (!card.isConnected) return;
          continue;
        }
        const previous = readCachedQuote(true);
        if (previous) {
          renderQuote(card, previous, "stale", error);
        } else {
          card.querySelector('[data-exchange="status"]').textContent = `${errorMessage(error)} · 暂无可用缓存，请稍后刷新`;
          card.classList.remove("is-loading", "is-online", "is-stale");
          card.classList.add("is-offline");
        }
        return;
      }
    }
  }

  function mountExchangeCard() {
    const homeContent = document.querySelector(".home-content-container");
    if (!homeContent) return;

    let card = document.getElementById("aud-cny-exchange-card");
    if (!card) {
      card = createCard();
      const weatherCard = document.getElementById("visitor-status-hud");
      if (weatherCard) weatherCard.insertAdjacentElement("afterend", card);
      else homeContent.prepend(card);
    }
    loadQuote(card);
  }

  function bindSwup(swup) {
    if (swupBound || !swup?.hooks) return;
    swupBound = true;
    swup.hooks.on("page:view", mountExchangeCard);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mountExchangeCard, { once: true });
  } else {
    mountExchangeCard();
  }

  if (window.swup?.hooks) {
    bindSwup(window.swup);
  } else {
    window.addEventListener(
      "redefine:swup:ready",
      (event) => bindSwup(event.detail?.swup || window.swup),
      { once: true }
    );
  }
})();

(() => {
  "use strict";

  const VISITOR_WEATHER_URL = "/api/visitor-weather";
  const CACHE_KEY = "aden-visitor-weather-v2";
  const CACHE_TTL = 10 * 60 * 1000;
  const REQUEST_TIMEOUT_MS = 15000;
  const RETRY_DELAY_MS = 1500;
  const ERROR_MESSAGES = {
    connection_timeout: "连接天气服务超时",
    connection_failed: "无法连接天气服务，请检查网络",
    location_unavailable: "暂时无法识别 IP 所在地区",
    weather_timeout: "天气数据源响应超时",
    weather_unavailable: "天气数据源暂不可用",
    invalid_response: "天气服务返回的数据异常",
    not_found: "天气接口不存在（404）",
    access_denied: "天气请求被拒绝",
    rate_limited: "天气请求过于频繁，请稍后再试",
    service_unavailable: "天气接口暂不可用"
  };

  let clockTimer = null;
  let swupBound = false;
  let activeTimeZone = getDeviceLocation().timezone;
  let timeFormatter = createTimeFormatter(activeTimeZone);
  let dateFormatter = createDateFormatter(activeTimeZone);

  const weatherCodes = {
    0: ["晴朗", "SUN", "☀"],
    1: ["大致晴朗", "CLEAR", "◒"],
    2: ["局部多云", "CLOUD", "◑"],
    3: ["阴天", "OVERCAST", "☁"],
    45: ["有雾", "FOG", "≋"],
    48: ["雾凇", "RIME", "≋"],
    51: ["小毛毛雨", "DRIZZLE", "⋰"],
    53: ["毛毛雨", "DRIZZLE", "⋰"],
    55: ["较强毛毛雨", "DRIZZLE", "⋰"],
    56: ["冻毛毛雨", "ICE RAIN", "❄"],
    57: ["较强冻毛毛雨", "ICE RAIN", "❄"],
    61: ["小雨", "RAIN", "⌁"],
    63: ["中雨", "RAIN", "⌁"],
    65: ["大雨", "HEAVY RAIN", "⌁"],
    66: ["冻雨", "ICE RAIN", "❄"],
    67: ["较强冻雨", "ICE RAIN", "❄"],
    71: ["小雪", "SNOW", "✦"],
    73: ["中雪", "SNOW", "✦"],
    75: ["大雪", "HEAVY SNOW", "✦"],
    77: ["米雪", "SNOW", "✦"],
    80: ["局部阵雨", "SHOWERS", "⌁"],
    81: ["阵雨", "SHOWERS", "⌁"],
    82: ["强阵雨", "SHOWERS", "⌁"],
    85: ["阵雪", "SNOW", "✦"],
    86: ["强阵雪", "SNOW", "✦"],
    95: ["雷暴", "STORM", "ϟ"],
    96: ["雷暴伴冰雹", "STORM", "ϟ"],
    99: ["强雷暴伴冰雹", "STORM", "ϟ"]
  };

  function createTimeFormatter(timeZone) {
    return new Intl.DateTimeFormat("en-AU", {
      timeZone,
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23"
    });
  }

  function createDateFormatter(timeZone) {
    return new Intl.DateTimeFormat("zh-CN", {
      timeZone,
      year: "numeric",
      month: "long",
      day: "numeric",
      weekday: "long"
    });
  }

  function isValidTimeZone(timeZone) {
    if (!timeZone) return false;
    try {
      new Intl.DateTimeFormat("en", { timeZone }).format();
      return true;
    } catch (_) {
      return false;
    }
  }

  function getTimeZoneName(timeZone) {
    try {
      const parts = new Intl.DateTimeFormat("en-AU", {
        timeZone,
        timeZoneName: "short"
      }).formatToParts(new Date());
      return parts.find((part) => part.type === "timeZoneName")?.value || timeZone;
    } catch (_) {
      return timeZone;
    }
  }

  function createCard() {
    const card = document.createElement("section");
    card.className = "cyber-weather-card";
    card.id = "visitor-status-hud";
    card.setAttribute("aria-label", "访客所在地时间与天气");
    card.innerHTML = `
      <div class="cyber-weather-header">
        <span class="cyber-weather-live"><i aria-hidden="true"></i> LIVE // <span data-location="name">LOCATING</span></span>
        <span class="cyber-weather-coords" data-location="timezone">LOCAL NODE</span>
      </div>
      <div class="cyber-weather-grid">
        <div class="cyber-clock-block">
          <span class="cyber-data-label" data-location="clock-label">LOCAL TIME / CALIBRATING</span>
          <time class="cyber-clock" datetime="">--:--:--</time>
          <span class="cyber-date">正在校准时间…</span>
        </div>
        <div class="cyber-current-weather" aria-live="polite">
          <span class="cyber-weather-icon" aria-hidden="true">◌</span>
          <div>
            <span class="cyber-temperature">--°</span>
            <span class="cyber-condition">正在识别访客地区…</span>
            <span class="cyber-feels-like">体感温度 --°C</span>
          </div>
        </div>
        <dl class="cyber-weather-metrics">
          <div><dt>HUMIDITY</dt><dd data-weather="humidity">--%</dd></div>
          <div><dt>WIND</dt><dd data-weather="wind">-- km/h</dd></div>
          <div><dt>SUNSET</dt><dd data-weather="sunset">--:--</dd></div>
        </dl>
      </div>
      <div class="cyber-weather-footer">
        <span data-weather="status">LOCATION LINK / CONNECTING</span>
        <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">DATA / OPEN-METEO</a>
      </div>`;
    return card;
  }

  function getDeviceLocation() {
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return { label: "设备时间", timezone: isValidTimeZone(timezone) ? timezone : "UTC" };
  }

  function applyLocation(card, location = getDeviceLocation()) {
    const timeZone = isValidTimeZone(location.timezone) ? location.timezone : getDeviceLocation().timezone;
    const label = String(location.label || location.city || location.region || location.country || "当前位置");
    activeTimeZone = timeZone;
    timeFormatter = createTimeFormatter(activeTimeZone);
    dateFormatter = createDateFormatter(activeTimeZone);

    card.querySelector('[data-location="name"]').textContent = label.toLocaleUpperCase();
    card.querySelector('[data-location="timezone"]').textContent = timeZone;
    card.querySelector('[data-location="clock-label"]').textContent = `LOCAL TIME / ${getTimeZoneName(timeZone)}`;
    card.setAttribute("aria-label", `${label}时间与天气`);
  }

  function updateClock(card) {
    if (!card?.isConnected) return;
    const now = new Date();
    const clock = card.querySelector(".cyber-clock");
    const date = card.querySelector(".cyber-date");
    clock.textContent = timeFormatter.format(now);
    clock.dateTime = now.toISOString();
    date.textContent = dateFormatter.format(now);
  }

  function formatNumber(value, fractionDigits = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number.toFixed(fractionDigits) : "--";
  }

  function renderWeather(card, payload, source = "vercel") {
    if (!card?.isConnected || !payload?.current) return;
    applyLocation(card, payload.location);
    updateClock(card);

    const current = payload.current;
    const [condition, codeLabel, icon] = weatherCodes[current.weather_code] || ["天气未知", "UNKNOWN", "◇"];
    const sunsetValue = payload.daily?.sunset?.[0];
    const sunset = typeof sunsetValue === "string" ? sunsetValue.slice(11, 16) : "--:--";

    card.querySelector(".cyber-weather-icon").textContent = icon;
    card.querySelector(".cyber-temperature").textContent = `${formatNumber(current.temperature_2m)}°`;
    card.querySelector(".cyber-condition").textContent = `${condition} / ${codeLabel}`;
    card.querySelector(".cyber-feels-like").textContent = `体感温度 ${formatNumber(current.apparent_temperature)}°C`;
    card.querySelector('[data-weather="humidity"]').textContent = `${formatNumber(current.relative_humidity_2m)}%`;
    card.querySelector('[data-weather="wind"]').textContent = `${formatNumber(current.wind_speed_10m)} km/h`;
    card.querySelector('[data-weather="sunset"]').textContent = sunset;

    const status = card.querySelector('[data-weather="status"]');
    if (source === "cache") status.textContent = "LOCATION LINK / CACHED";
    else status.textContent = "LOCATION LINK / IP APPROX";
    card.classList.remove("is-offline");
    card.classList.add("is-online");
  }

  function isValidWeather(payload) {
    return Boolean(
      payload &&
      typeof payload.location === "object" &&
      payload.location !== null &&
      payload.location.source !== "fallback" &&
      typeof payload.location.timezone === "string" &&
      isValidTimeZone(payload.location.timezone) &&
      payload.current &&
      Number.isFinite(payload.current.temperature_2m) &&
      Number.isFinite(payload.current.weather_code)
    );
  }

  function clearCachedWeather() {
    try {
      sessionStorage.removeItem(CACHE_KEY);
    } catch (_) {
      // Storage may be blocked entirely, including removal. It is optional.
    }
  }

  function readCachedWeather() {
    try {
      const cached = JSON.parse(sessionStorage.getItem(CACHE_KEY));
      const age = Date.now() - cached?.savedAt;
      if (
        Number.isFinite(cached?.savedAt) &&
        age >= 0 &&
        age < CACHE_TTL &&
        isValidWeather(cached.payload)
      ) return cached.payload;
    } catch (_) {
      // Unreadable or malformed cache must not prevent a network request.
    }
    clearCachedWeather();
    return null;
  }

  function cacheWeather(payload) {
    try {
      sessionStorage.setItem(CACHE_KEY, JSON.stringify({ savedAt: Date.now(), payload }));
    } catch (_) {
      // The card still works when storage is unavailable.
    }
  }

  function weatherError(code) {
    return Object.assign(new Error(code), { code });
  }

  function errorMessage(error) {
    return ERROR_MESSAGES[error?.code] || ERROR_MESSAGES.service_unavailable;
  }

  function canRetry(error) {
    return ["connection_timeout", "connection_failed", "weather_timeout", "weather_unavailable", "service_unavailable"].includes(error?.code);
  }

  async function fetchJson(url, timeoutMs = REQUEST_TIMEOUT_MS) {
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: { Accept: "application/json" }
      });
      let payload;
      try {
        payload = await response.json();
      } catch (error) {
        if (error?.name === "AbortError") throw error;
        if (response.ok) throw weatherError("invalid_response");
      }
      if (!response.ok) {
        const statusCode = { 404: "not_found", 401: "access_denied", 403: "access_denied", 429: "rate_limited" }[response.status];
        const sourceCode = ["location_unavailable", "weather_timeout", "weather_unavailable"].includes(payload?.error) ? payload.error : null;
        throw weatherError(statusCode || sourceCode || "service_unavailable");
      }
      return payload;
    } catch (error) {
      if (controller.signal.aborted || error?.name === "AbortError") throw weatherError("connection_timeout");
      throw error?.code ? error : weatherError("connection_failed");
    } finally {
      window.clearTimeout(timeout);
    }
  }

  async function loadWeather(card) {
    try {
      const cached = readCachedWeather();
      if (cached) {
        renderWeather(card, cached, "cache");
        return;
      }
    } catch (_) {
      // A cached payload that cannot render must fall through to a fresh request.
      clearCachedWeather();
    }

    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        const payload = await fetchJson(VISITOR_WEATHER_URL);
        if (!isValidWeather(payload)) throw weatherError("invalid_response");
        cacheWeather(payload);
        renderWeather(card, payload, "vercel");
        return;
      } catch (error) {
        if (!card?.isConnected) return;
        if (attempt === 0 && canRetry(error)) {
          card.querySelector(".cyber-condition").textContent = `${errorMessage(error)}，正在重试…`;
          card.querySelector('[data-weather="status"]').textContent = "LOCATION LINK / RETRY 1/1";
          await new Promise(resolve => window.setTimeout(resolve, RETRY_DELAY_MS));
          if (!card.isConnected) return;
          continue;
        }
        applyLocation(card, getDeviceLocation());
        updateClock(card);
        card.querySelector(".cyber-temperature").textContent = "--°";
        card.querySelector(".cyber-weather-icon").textContent = "!";
        card.querySelector(".cyber-feels-like").textContent = "已保留设备时区 · 可稍后刷新重试";
        for (const [key, value] of [["humidity", "--%"], ["wind", "-- km/h"], ["sunset", "--:--"]]) {
          card.querySelector(`[data-weather="${key}"]`).textContent = value;
        }
        card.querySelector(".cyber-condition").textContent = errorMessage(error);
        card.querySelector('[data-weather="status"]').textContent = "LOCATION LINK / OFFLINE · 设备时间";
        card.classList.remove("is-online");
        card.classList.add("is-offline");
        return;
      }
    }
  }

  function mountWeatherCard() {
    if (clockTimer) {
      window.clearInterval(clockTimer);
      clockTimer = null;
    }

    const homeContent = document.querySelector(".home-content-container");
    if (!homeContent) return;

    let card = document.getElementById("visitor-status-hud");
    if (!card) {
      card = createCard();
      homeContent.prepend(card);
    }

    applyLocation(card, {
      ...getDeviceLocation(),
      label: "定位中",
    });
    updateClock(card);
    clockTimer = window.setInterval(() => updateClock(card), 1000);
    loadWeather(card);
  }

  function bindSwup(swup) {
    if (swupBound || !swup?.hooks) return;
    swupBound = true;
    swup.hooks.on("page:view", mountWeatherCard);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mountWeatherCard, { once: true });
  } else {
    mountWeatherCard();
  }

  if (window.swup?.hooks) {
    bindSwup(window.swup);
  } else {
    window.addEventListener(
      "redefine:swup:ready",
      (event) => bindSwup(event.detail?.swup || window.swup),
      { once: true }
    );
  }
})();

(() => {
  const root = document.documentElement;
  const storageKey = "REDEFINE-THEME-STATUS";

  try {
    const raw = window.localStorage.getItem(storageKey);
    let status = {};

    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object") status = parsed;
    }

    if (typeof status.isDark !== "boolean") {
      status.isDark = true;
      window.localStorage.setItem(storageKey, JSON.stringify(status));
      root.classList.remove("light");
      root.classList.add("dark");
    }
  } catch (error) {
    root.classList.remove("light");
    root.classList.add("dark");
  }

  const syncColorScheme = () => {
    root.style.colorScheme = root.classList.contains("light") ? "light" : "dark";
  };

  syncColorScheme();

  if (!window.__adenThemeModeObserver) {
    window.__adenThemeModeObserver = new MutationObserver(syncColorScheme);
    window.__adenThemeModeObserver.observe(root, {
      attributes: true,
      attributeFilter: ["class"],
    });
  }

  document.addEventListener("DOMContentLoaded", syncColorScheme, { once: true });
})();
